from collections import Counter


def transform(grid):
    H = len(grid)
    W = len(grid[0])
    bg = Counter(c for row in grid for c in row).most_common(1)[0][0]

    # connected components of same-colored non-background cells (4-connectivity)
    seen = set()
    comps = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] != bg and (i, j) not in seen:
                color = grid[i][j]
                stack = [(i, j)]
                seen.add((i, j))
                cells = []
                while stack:
                    r, c = stack.pop()
                    cells.append((r, c))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if (0 <= nr < H and 0 <= nc < W and (nr, nc) not in seen
                                and grid[nr][nc] == color):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
                comps.append((color, frozenset(cells)))

    def bbox(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    # find template: L-shaped (size == h+w-1), bordering grid, box-complement has exactly 2 colors
    best = None
    for color, cells in comps:
        r0, r1, c0, c1 = bbox(cells)
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if len(cells) != h + w - 1:
            continue
        if not any(r in (0, H - 1) or c in (0, W - 1) for r, c in cells):
            continue
        comp_colors = set()
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if (r, c) not in cells:
                    comp_colors.add(grid[r][c])
        if len(comp_colors) != 2:
            continue
        if best is None or len(cells) > len(best[2]):
            best = (color, comp_colors, cells)

    if best is None:
        return grid

    tcolor, _, tcells = best
    r0, r1, c0, c1 = bbox(tcells)

    # embedded shape: non-background cells inside the box but outside the template
    emb = frozenset((r, c)
                    for r in range(r0, r1 + 1)
                    for c in range(c0, c1 + 1)
                    if (r, c) not in tcells and grid[r][c] != bg)

    def norm(cells):
        nr = min(r for r, c in cells)
        nc = min(c for r, c in cells)
        return frozenset((r - nr, c - nc) for r, c in cells)

    nemb = norm(emb)

    out = [row[:] for row in grid]
    for color, cells in comps:
        if cells == emb:
            continue
        if norm(cells) == nemb:
            for r, c in cells:
                out[r][c] = tcolor
            return out
    return out

