def transform(grid):
    from collections import Counter
    R = len(grid); C = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    colors = [c for c in cnt if c != bg]

    def comps(cells):
        s = set(cells); out = []
        while s:
            start = s.pop(); stack = [start]; comp = [start]
            while stack:
                r, c = stack.pop()
                for nr, nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                    if (nr, nc) in s:
                        s.remove((nr, nc)); stack.append((nr, nc)); comp.append((nr, nc))
            out.append(comp)
        return out

    B = None; bars = None
    for col in colors:
        cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == col]
        if not cells: continue
        if not all(r in (0, R-1) or c in (0, C-1) for r, c in cells): continue
        cs = comps(cells)
        if len(cs) == 2 and all(len(x) > 1 for x in cs):
            B = col; bars = cs
    S = [c for c in colors if c != B][0]
    seeds = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == S]

    seedrows = {r for r, _ in seeds}; seedcols = {c for _, c in seeds}
    def shares(bar):
        return ({r for r, _ in bar} & seedrows) or ({c for _, c in bar} & seedcols)
    M = next(b for b in bars if shares(b))
    O = next(b for b in bars if b is not M)

    Mrows = sorted({r for r, _ in M}); Mcols = sorted({c for _, c in M})
    Orows = sorted({r for r, _ in O}); Ocols = sorted({c for _, c in O})
    allrows = sorted({r for r, _ in bars[0] + bars[1]})
    allcols = sorted({c for _, c in bars[0] + bars[1]})
    horizontal = len(allrows) > len(allcols)

    out = [row[:] for row in grid]

    # 1. connect each seed toward matching bar M
    for (r, c) in seeds:
        if r in Mrows:
            if c < Mcols[0]: land = Mcols[0] - 1
            elif c > Mcols[-1]: land = Mcols[-1] + 1
            else: continue
            for cc in range(min(c, land), max(c, land) + 1):
                out[r][cc] = S
        elif c in Mcols:
            if r < Mrows[0]: land = Mrows[0] - 1
            elif r > Mrows[-1]: land = Mrows[-1] + 1
            else: continue
            for rr in range(min(r, land), max(r, land) + 1):
                out[rr][c] = S

    # 2. seed cells become 4
    for (r, c) in seeds:
        out[r][c] = 4

    # 3. shifted seeds -> full rows/cols, clamped to O's extent
    if horizontal:
        dr = Orows[0] - Mrows[0]
        lines = set()
        for (r, c) in seeds:
            nr = r + dr
            nr = min(max(nr, Orows[0]), Orows[-1])
            lines.add(nr)
        for nr in lines:
            for cc in range(C):
                out[nr][cc] = S
    else:
        dc = Ocols[0] - Mcols[0]
        lines = set()
        for (r, c) in seeds:
            nc = c + dc
            nc = min(max(nc, Ocols[0]), Ocols[-1])
            lines.add(nc)
        for nc in lines:
            for rr in range(R):
                out[rr][nc] = S

    # 4. restore bar cells
    for bar in bars:
        for (r, c) in bar:
            out[r][c] = B

    return out

